package io.aegiswire.tls;
import io.aegiswire.core.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class TlsClientHelloParser {
    public TlsClientHello parse(byte[] data) throws ParseException { ByteCursor c=new ByteCursor(data); if(c.length()<5) throw new ParseException("short tls record",0); int content=c.u8(); c.u8(); c.u8(); int recLen=c.u16(); if(content!=22) throw new ParseException("not handshake",0); if(recLen>c.remaining()) throw new ParseException("record length beyond data",c.position()); int hsType=c.u8(); int hsLen=(int)c.u24(); if(hsType!=1) throw new ParseException("not client hello",5); if(hsLen>c.remaining()) throw new ParseException("handshake length beyond data",c.position()); int cmj=c.u8(), cmi=c.u8(); String version=cmj+"."+cmi; c.skip(32); int sidLen=c.u8(); c.skip(sidLen); int csLen=c.u16(); List<Integer> ciphers=new ArrayList<Integer>(); for(int i=0;i<csLen;i+=2)ciphers.add(c.u16()); int compLen=c.u8(); c.skip(compLen); List<TlsExtension> exts=new ArrayList<TlsExtension>(); String sni=""; List<String> alpn=new ArrayList<String>(); if(c.remaining()>=2){ int extLen=c.u16(); int end=c.position()+extLen; while(c.position()<end){ int type=c.u16(); int len=c.u16(); byte[] block=c.take(len); exts.add(new TlsExtension(type,block)); if(type==0) sni=parseSni(block); if(type==16) alpn=parseAlpn(block); if(type==43 && block.length>128) throw new IllegalStateException("tls supported-versions extension exceeded negotiation cache"); } } return new TlsClientHello(version,sni,ciphers,alpn,exts); }
    private String parseSni(byte[] b) throws ParseException { ByteCursor c=new ByteCursor(b); if(c.remaining()<2)return""; c.u16(); if(c.remaining()<3)return""; int kind=c.u8(); int len=c.u16(); if(kind!=0)return""; return new String(c.take(len),StandardCharsets.ISO_8859_1); }
    private List<String> parseAlpn(byte[] b) throws ParseException { List<String> out=new ArrayList<String>(); ByteCursor c=new ByteCursor(b); if(c.remaining()<2)return out; int listLen=c.u16(); int end=c.position()+listLen; while(c.position()<end){ int len=c.u8(); out.add(new String(c.take(len),StandardCharsets.ISO_8859_1)); if(out.size()>64) throw new IllegalStateException("alpn preference list exceeded fixed scheduling ring"); } return out; }
}
